package de.kopfzentrum.gam.inventory;
import de.kopfzentrum.gam.auth.AuthenticatedUser;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/inventory/discovery/homeassistant") @PreAuthorize("hasAnyRole('SUPERADMIN','ADMIN')")
public class HomeAssistantSettingsController {private final HomeAssistantSettingsRepository settings;private final HomeAssistantDeviceSource source;public HomeAssistantSettingsController(HomeAssistantSettingsRepository s,HomeAssistantDeviceSource d){settings=s;source=d;}@GetMapping("/sources")public List<HomeAssistantSettingsRepository.View> list(){return settings.loadViews();}@PostMapping("/sources")public HomeAssistantSettingsRepository.View create(@RequestBody HomeAssistantSettingsRepository.Update u,@AuthenticationPrincipal AuthenticatedUser a){return settings.create(u,a==null?"system":a.getUsername());}@PutMapping("/sources/{id}")public HomeAssistantSettingsRepository.View save(@PathVariable long id,@RequestBody HomeAssistantSettingsRepository.Update u,@AuthenticationPrincipal AuthenticatedUser a){return settings.save(id,u,a==null?"system":a.getUsername());}@DeleteMapping("/sources/{id}")public void delete(@PathVariable long id){settings.delete(id);}@PostMapping("/sources/{id}/test")public HomeAssistantDeviceSource.TestResult test(@PathVariable long id){return source.test(id);}}
